WITH duplicates AS ( SELECT d.id,d.path,first_value(d.id) OVER (PARTITION BY v.content_hash ORDER BY d.path,d.id) AS canonical_id, first_value(d.path) OVER (PARTITION BY v.content_hash ORDER BY d.path,d.id) AS canonical_path FROM source_documents d JOIN document_revisions v ON v.source_document_id=d.id AND v.is_current WHERE d.project_id=$1 AND d.is_current AND d.freshness_status='current' ) UPDATE source_documents d SET freshness_status='duplicate',duplicate_of_document_id=duplicates.canonical_id FROM duplicates WHERE d.id=duplicates.id AND duplicates.path<>duplicates.canonical_path
